USER_TABLES = ("portfolios", "transactions", "watchlists", "watchlist_items")
# Child rows must also hang off a parent the same user owns.
PARENT_CHECK = {
    "transactions": "exists (select 1 from portfolios p where p.id = portfolio_id "
    "and p.user_id = (select auth.uid()))",
    "watchlist_items": "exists (select 1 from watchlists w where w.id = watchlist_id "
    "and w.user_id = (select auth.uid()))",
}


def _user_foreign_keys() -> None:
    # Same pattern as profiles (0001): on Supabase the app role lacks REFERENCES
    # on auth.users, so infra/supabase/setup.sql adds these as postgres.
    for table in USER_TABLES:
        op.execute(
            f"""
            do $$ begin
              if has_table_privilege(current_user, 'auth.users', 'REFERENCES') then
                alter table {table} add constraint fk_{table}_user_id_users
                  foreign key (user_id) references auth.users (id) on delete cascade;
              else
                raise notice 'fk_{table}_user_id_users skipped: run infra/supabase/setup.sql';
              end if;
            end $$;
            """
        )


def _row_level_security() -> None:
    for table in USER_TABLES:
        own = "(select auth.uid()) = user_id"
        check = f"{own} and {PARENT_CHECK[table]}" if table in PARENT_CHECK else own
        op.execute(f"alter table {table} enable row level security")
        op.execute(
            f"create policy {table}_select_own on {table} for select to authenticated using ({own})"
        )
        op.execute(
            f"create policy {table}_insert_own on {table} for insert to authenticated "
            f"with check ({check})"
        )
        op.execute(
            f"create policy {table}_update_own on {table} for update to authenticated "
            f"using ({own}) with check ({check})"
        )
        op.execute(
            f"create policy {table}_delete_own on {table} for delete to authenticated using ({own})"
        )
        op.execute(f"grant select, insert, update, delete on {table} to authenticated")
